    "",
    "import sys, json\nimport itertools, functools, collections, math, bisect, string, heapq, random, operator\nfrom typing import *\nfrom collections import *\nfrom itertools import *\nfrom bisect import *\nfrom functools import *\nfrom math import *\nfrom string import *\nfrom operator import *\n\nclass Solution:\n    def numberOfSets(self, n: int, maxDistance: int, roads: List[List[int]]) -> int:\n        res = 0\n        opened = [0] * n\n        for mask in range(1 << n):\n            for i in range(n):\n                opened[i] = mask & (1 << i)\n            d = [[1000000] * n for i in range(n)]\n            for i,j,r in roads:\n                if opened[i] > 0 and opened[j] > 0:\n                    d[i][j] = d[j][i] = min(d[i][j], r)\n            for k in range(n):\n                if opened[k] > 0:\n                    for i in range(n):\n                        if opened[i] > 0:\n                            for j in range(i + 1, n):\n                                if opened[j] > 0:\n                                    d[i][j] = d[j][i] = min(d[i][j], d[i][k] + d[k][j])\n            good = 1\n            for i in range(n):\n                if opened[i] > 0:\n                    for j in range(i + 1, n):\n                        if opened[j] > 0:\n                            if d[i][j] > maxDistance:\n                                good = 0\n                                break\n                if good == 0:\n                    break\n            res += good\n        return res\n\ndef main():\n    _dec = json.JSONDecoder()\n    _text = sys.stdin.read()\n    _idx = 0\n    _args = []\n    while _idx < len(_text):\n        while _idx < len(_text) and _text[_idx] in ' \\t\\r\\n':\n            _idx += 1\n        if _idx >= len(_text):\n            break\n        try:\n            _obj, _end = _dec.raw_decode(_text, _idx)\n            _args.append(_obj)\n            _idx = _end\n        except Exception:\n            _nl = _text.find('\\n', _idx)\n            if _nl == -1:\n                _idx = len(_text)\n            else:\n                _idx = _nl + 1\n    _sol = Solution()\n\n    _ret = _sol.numberOfSets(_args[0], _args[1], _args[2])\n    if _ret is None:\n        _out = ''\n    elif isinstance(_ret, (list, dict)):\n        _out = json.dumps(_ret, separators=(',', ':'))\n    elif isinstance(_ret, bool):\n        _out = 'true' if _ret else 'false'\n    elif isinstance(_ret, float):\n        _out = repr(_ret)\n    else:\n        _out = str(_ret)\n    sys.stdout.write(_out)\n\nmain()\n",
