PGH06 = mk(
    "GH06",
    "\u8f6c\u5316\u4e3a\u5168\u96f6\u77e9\u9635\u7684\u6700\u5c11\u53cd\u8f6c\u6b21\u6570",
    "LeetCode 1284",
    "hard",
    "\u56fe",
    "\u7ed9\u4f60\u4e00\u4e2a\u00a0m x n\u00a0\u7684\u4e8c\u8fdb\u5236\u77e9\u9635\u00a0mat\u3002\u6bcf\u4e00\u6b65\uff0c\u4f60\u53ef\u4ee5\u9009\u62e9\u4e00\u4e2a\u5355\u5143\u683c\u5e76\u5c06\u5b83\u53cd\u8f6c\uff08\u53cd\u8f6c\u8868\u793a 0 \u53d8 1 \uff0c1 \u53d8 0 \uff09\u3002\u5982\u679c\u5b58\u5728\u548c\u5b83\u76f8\u90bb\u7684\u5355\u5143\u683c\uff0c\u90a3\u4e48\u8fd9\u4e9b\u76f8\u90bb\u7684\u5355\u5143\u683c\u4e5f\u4f1a\u88ab\u53cd\u8f6c\u3002\u76f8\u90bb\u7684\u4e24\u4e2a\u5355\u5143\u683c\u5171\u4eab\u540c\u4e00\u6761\u8fb9\u3002\n\n\u8bf7\u4f60\u8fd4\u56de\u5c06\u77e9\u9635\u00a0mat \u8f6c\u5316\u4e3a\u5168\u96f6\u77e9\u9635\u7684\u6700\u5c11\u53cd\u8f6c\u6b21\u6570\uff0c\u5982\u679c\u65e0\u6cd5\u8f6c\u5316\u4e3a\u5168\u96f6\u77e9\u9635\uff0c\u8bf7\u8fd4\u56de\u00a0-1\u00a0\u3002\n\n\u4e8c\u8fdb\u5236\u77e9\u9635\u00a0\u7684\u6bcf\u4e00\u4e2a\u683c\u5b50\u8981\u4e48\u662f 0 \u8981\u4e48\u662f 1 \u3002\n\n\u5168\u96f6\u77e9\u9635\u00a0\u662f\u6240\u6709\u683c\u5b50\u90fd\u4e3a 0 \u7684\u77e9\u9635\u3002\n\n\u00a0\n\n\u793a\u4f8b\u00a01\uff1a\n\n```\n\u8f93\u5165\uff1amat = [[0,0],[0,1]]\n\u8f93\u51fa\uff1a3\n\u89e3\u91ca\uff1a\u4e00\u4e2a\u53ef\u80fd\u7684\u89e3\u662f\u53cd\u8f6c (1, 0)\uff0c\u7136\u540e (0, 1) \uff0c\u6700\u540e\u662f (1, 1) \u3002\n```\n\n\u793a\u4f8b 2\uff1a\n\n```\n\u8f93\u5165\uff1amat = [[0]]\n\u8f93\u51fa\uff1a0\n\u89e3\u91ca\uff1a\u7ed9\u51fa\u7684\u77e9\u9635\u662f\u5168\u96f6\u77e9\u9635\uff0c\u6240\u4ee5\u4f60\u4e0d\u9700\u8981\u6539\u53d8\u5b83\u3002\n```\n\n\u793a\u4f8b 3\uff1a\n\n```\n\u8f93\u5165\uff1amat = [[1,0,0],[1,0,0]]\n\u8f93\u51fa\uff1a-1\n\u89e3\u91ca\uff1a\u8be5\u77e9\u9635\u65e0\u6cd5\u8f6c\u53d8\u6210\u5168\u96f6\u77e9\u9635\n```\n\n\u00a0\n\n\u63d0\u793a\uff1a\n\n\tm ==\u00a0mat.length\n\n\tn ==\u00a0mat[0].length\n\n\t1 <= m\u00a0<= 3\n\n\t1 <= n\u00a0<= 3\n\n\tmat[i][j]\u00a0\u662f 0 \u6216 1 \u3002",
    "\u6bcf\u884c\u4e00\u4e2a\u53c2\u6570\uff08JSON \u683c\u5f0f\uff09\uff0c\u4f9d\u6b21\u4e3a\uff1amat\u3002",
    "\u8f93\u51fa integer \u7c7b\u578b\u7ed3\u679c\uff08JSON \u5e8f\u5217\u5316\uff09\u3002",
    "",
    "import sys, json\nimport itertools, functools, collections, math, bisect, string, heapq, random, operator\nfrom typing import *\nfrom collections import *\nfrom itertools import *\nfrom bisect import *\nfrom functools import *\nfrom math import *\nfrom string import *\nfrom operator import *\n\nclass Solution:\n    def encode(self, mat, m, n):\n        x = 0\n        for i in range(m):\n            for j in range(n):\n                x = x * 2 + mat[i][j]\n        return x\n\n    def decode(self, x, m, n):\n        mat = [[0] * n for _ in range(m)]\n        for i in range(m - 1, -1, -1):\n            for j in range(n - 1, -1, -1):\n                mat[i][j] = x & 1\n                x >>= 1\n        return mat\n\n    def convert(self, mat, m, n, i, j):\n        for di, dj in [(-1, 0), (1, 0), (0, -1), (0, 1), (0, 0)]:\n            i0, j0 = i + di, j + dj\n            if 0 <= i0 < m and 0 <= j0 < n:\n                mat[i0][j0] ^= 1\n\n    def minFlips(self, mat: List[List[int]]) -> int:\n        m, n = len(mat), len(mat[0])\n        x_start, step = self.encode(mat, m, n), 0\n        if x_start == 0:\n            return step\n\n        visited = {x_start}\n        q = queue.Queue()\n        q.put_nowait(x_start)\n\n        while not q.empty():\n            step += 1\n            k = q.qsize()\n            for _ in range(k):\n                status = self.decode(q.get_nowait(), m, n)\n                for i in range(m):\n                    for j in range(n):\n                        self.convert(status, m, n, i, j)\n                        x_cur = self.encode(status, m, n)\n                        if x_cur == 0:\n                            return step\n                        if x_cur not in visited:\n                            visited.add(x_cur)\n                            q.put_nowait(x_cur)\n                        self.convert(status, m, n, i, j)\n\n        return -1\n\ndef main():\n    _dec = json.JSONDecoder()\n    _text = sys.stdin.read()\n    _idx = 0\n    _args = []\n    while _idx < len(_text):\n        while _idx < len(_text) and _text[_idx] in ' \\t\\r\\n':\n            _idx += 1\n        if _idx >= len(_text):\n            break\n        try:\n            _obj, _end = _dec.raw_decode(_text, _idx)\n            _args.append(_obj)\n            _idx = _end\n        except Exception:\n            _nl = _text.find('\\n', _idx)\n            if _nl == -1:\n                _idx = len(_text)\n            else:\n                _idx = _nl + 1\n    _sol = Solution()\n\n    _ret = _sol.minFlips(_args[0])\n    if _ret is None:\n        _out = ''\n    elif isinstance(_ret, (list, dict)):\n        _out = json.dumps(_ret, separators=(',', ':'))\n    elif isinstance(_ret, bool):\n        _out = 'true' if _ret else 'false'\n    elif isinstance(_ret, float):\n        _out = repr(_ret)\n    else:\n        _out = str(_ret)\n    sys.stdout.write(_out)\n\nmain()\n",
    "int",
    [["[[0]]", "0"]],
    ["bit-manipulation", "breadth-first-search", "array", "hash-table", "matrix", "\u56fe"],
    )
