    "import sys, json\nimport itertools, functools, collections, math, bisect, string, heapq, random, operator\nfrom typing import *\nfrom collections import *\nfrom itertools import *\nfrom bisect import *\nfrom functools import *\nfrom math import *\nfrom string import *\nfrom operator import *\n\nclass Solution:\n    def maximalPathQuality(self, values: List[int], edges: List[List[int]], maxTime: int) -> int:\n        g = defaultdict(list)\n        for x, y, z in edges:\n            g[x].append((y, z))\n            g[y].append((x, z))\n        \n        visited = {0}\n        ans = 0\n        \n        def dfs(u: int, time: int, value: int) -> None:\n            if u == 0:\n                nonlocal ans\n                ans = max(ans, value)\n            for v, dist in g[u]:\n                if time + dist <= maxTime:\n                    if v not in visited:\n                        visited.add(v)\n                        dfs(v, time + dist, value + values[v])\n                        visited.discard(v)\n                    else:\n                        dfs(v, time + dist, value)\n        \n        dfs(0, 0, values[0])\n        return ans\n\ndef main():\n    _dec = json.JSONDecoder()\n    _text = sys.stdin.read()\n    _idx = 0\n    _args = []\n    while _idx < len(_text):\n        while _idx < len(_text) and _text[_idx] in ' \\t\\r\\n':\n            _idx += 1\n        if _idx >= len(_text):\n            break\n        try:\n            _obj, _end = _dec.raw_decode(_text, _idx)\n            _args.append(_obj)\n            _idx = _end\n        except Exception:\n            _nl = _text.find('\\n', _idx)\n            if _nl == -1:\n                _idx = len(_text)\n            else:\n                _idx = _nl + 1\n    _sol = Solution()\n\n    _ret = _sol.maximalPathQuality(_args[0], _args[1], _args[2])\n    if _ret is None:\n        _out = ''\n    elif isinstance(_ret, (list, dict)):\n        _out = json.dumps(_ret, separators=(',', ':'))\n    elif isinstance(_ret, bool):\n        _out = 'true' if _ret else 'false'\n    elif isinstance(_ret, float):\n        _out = repr(_ret)\n    else:\n        _out = str(_ret)\n    sys.stdout.write(_out)\n\nmain()\n",
