    "",
    "import sys, json\nimport itertools, functools, collections, math, bisect, string, heapq, random, operator\nfrom typing import *\nfrom collections import *\nfrom itertools import *\nfrom bisect import *\nfrom functools import *\nfrom math import *\nfrom string import *\nfrom operator import *\n\nclass Solution:\n    def containVirus(self, isInfected: List[List[int]]) -> int:\n        dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]\n        \n        m, n = len(isInfected), len(isInfected[0])\n        ans = 0\n\n        while True:\n            neighbors, firewalls = list(), list()\n            for i in range(m):\n                for j in range(n):\n                    if isInfected[i][j] == 1:\n                        q = deque([(i, j)])\n                        neighbor = set()\n                        firewall, idx = 0, len(neighbors) + 1\n                        isInfected[i][j] = -idx\n\n                        while q:\n                            x, y = q.popleft()\n                            for d in range(4):\n                                nx, ny = x + dirs[d][0], y + dirs[d][1]\n                                if 0 <= nx < m and 0 <= ny < n:\n                                    if isInfected[nx][ny] == 1:\n                                        q.append((nx, ny))\n                                        isInfected[nx][ny] = -idx\n                                    elif isInfected[nx][ny] == 0:\n                                        firewall += 1\n                                        neighbor.add((nx, ny))\n                        \n                        neighbors.append(neighbor)\n                        firewalls.append(firewall)\n            \n            if not neighbors:\n                break\n\n            idx = 0\n            for i in range(1, len(neighbors)):\n                if len(neighbors[i]) > len(neighbors[idx]):\n                    idx = i\n                \n            ans += firewalls[idx]\n            for i in range(m):\n                for j in range(n):\n                    if isInfected[i][j] < 0:\n                        if isInfected[i][j] != -idx - 1:\n                            isInfected[i][j] = 1\n                        else:\n                            isInfected[i][j] = 2\n            \n            for i, neighbor in enumerate(neighbors):\n                if i != idx:\n                    for x, y in neighbor:\n                        isInfected[x][y] = 1\n            \n            if len(neighbors) == 1:\n                break\n        \n        return ans\n\ndef main():\n    _dec = json.JSONDecoder()\n    _text = sys.stdin.read()\n    _idx = 0\n    _args = []\n    while _idx < len(_text):\n        while _idx < len(_text) and _text[_idx] in ' \\t\\r\\n':\n            _idx += 1\n        if _idx >= len(_text):\n            break\n        try:\n            _obj, _end = _dec.raw_decode(_text, _idx)\n            _args.append(_obj)\n            _idx = _end\n        except Exception:\n            _nl = _text.find('\\n', _idx)\n            if _nl == -1:\n                _idx = len(_text)\n            else:\n                _idx = _nl + 1\n    _sol = Solution()\n\n    _ret = _sol.containVirus(_args[0])\n    if _ret is None:\n        _out = ''\n    elif isinstance(_ret, (list, dict)):\n        _out = json.dumps(_ret, separators=(',', ':'))\n    elif isinstance(_ret, bool):\n        _out = 'true' if _ret else 'false'\n    elif isinstance(_ret, float):\n        _out = repr(_ret)\n    else:\n        _out = str(_ret)\n    sys.stdout.write(_out)\n\nmain()\n",
