    "import sys, json\nimport itertools, functools, collections, math, bisect, string, heapq, random, operator\nfrom typing import *\nfrom collections import *\nfrom itertools import *\nfrom bisect import *\nfrom functools import *\nfrom math import *\nfrom string import *\nfrom operator import *\n\nclass Solution:\n    def getf(self, f, x):\n        if f[x] == x:\n            return x\n        newf = self.getf(f, f[x])\n        f[x] = newf\n        return newf\n\n    def add(self, f, x, y):\n        fx = self.getf(f, x)\n        fy = self.getf(f, y)\n        f[fx] = fy\n\n    def minSwapsCouples(self, row: List[int]) -> int:\n        n = len(row)\n        tot = n // 2\n        f = [i for i in range(tot)]\n\n        for i in range(0, n, 2):\n            l = row[i] // 2\n            r = row[i + 1] // 2\n            self.add(f, l, r)\n\n        m = {}\n        for i in range(tot):\n            fx = self.getf(f, i)\n            if fx in m:\n                m[fx] += 1\n            else:\n                m[fx] = 1\n\n        ret = 0\n        for f, sz in m.items():\n            ret += sz - 1\n\n        return ret\n\ndef main():\n    _dec = json.JSONDecoder()\n    _text = sys.stdin.read()\n    _idx = 0\n    _args = []\n    while _idx < len(_text):\n        while _idx < len(_text) and _text[_idx] in ' \\t\\r\\n':\n            _idx += 1\n        if _idx >= len(_text):\n            break\n        try:\n            _obj, _end = _dec.raw_decode(_text, _idx)\n            _args.append(_obj)\n            _idx = _end\n        except Exception:\n            _nl = _text.find('\\n', _idx)\n            if _nl == -1:\n                _idx = len(_text)\n            else:\n                _idx = _nl + 1\n    _sol = Solution()\n\n    _ret = _sol.minSwapsCouples(_args[0])\n    if _ret is None:\n        _out = ''\n    elif isinstance(_ret, (list, dict)):\n        _out = json.dumps(_ret, separators=(',', ':'))\n    elif isinstance(_ret, bool):\n        _out = 'true' if _ret else 'false'\n    elif isinstance(_ret, float):\n        _out = repr(_ret)\n    else:\n        _out = str(_ret)\n    sys.stdout.write(_out)\n\nmain()\n",
