    "hard",
    "\u56fe",
    "\u7ed9\u4f60\u4e00\u4e2a\u6709\u00a0n\u00a0\u4e2a\u8282\u70b9\u7684\u00a0\u6709\u5411\u5e26\u6743\u00a0\u56fe\uff0c\u8282\u70b9\u7f16\u53f7\u4e3a\u00a00\u00a0\u5230\u00a0n - 1\u00a0\u3002\u56fe\u4e2d\u7684\u521d\u59cb\u8fb9\u7528\u6570\u7ec4\u00a0edges\u00a0\u8868\u793a\uff0c\u5176\u4e2d\u00a0edges[i] = [fromi, toi, edgeCosti]\u00a0\u8868\u793a\u4ece\u00a0fromi\u00a0\u5230\u00a0toi\u00a0\u6709\u4e00\u6761\u4ee3\u4ef7\u4e3a\u00a0edgeCosti\u00a0\u7684\u8fb9\u3002\n\n\u8bf7\u4f60\u5b9e\u73b0\u4e00\u4e2a\u00a0Graph\u00a0\u7c7b\uff1a\n\n\tGraph(int n, int[][] edges)\u00a0\u521d\u59cb\u5316\u56fe\u6709\u00a0n\u00a0\u4e2a\u8282\u70b9\uff0c\u5e76\u8f93\u5165\u521d\u59cb\u8fb9\u3002\n\n\taddEdge(int[] edge)\u00a0\u5411\u8fb9\u96c6\u4e2d\u6dfb\u52a0\u4e00\u6761\u8fb9\uff0c\u5176\u4e2d\u00a0edge = [from, to, edgeCost]\u00a0\u3002\u6570\u636e\u4fdd\u8bc1\u6dfb\u52a0\u8fd9\u6761\u8fb9\u4e4b\u524d\u5bf9\u5e94\u7684\u4e24\u4e2a\u8282\u70b9\u4e4b\u95f4\u6ca1\u6709\u6709\u5411\u8fb9\u3002\n\n\tint shortestPath(int node1, int node2)\u00a0\u8fd4\u56de\u4ece\u8282\u70b9\u00a0node1\u00a0\u5230\u00a0node2\u00a0\u7684\u8def\u5f84\u00a0\u6700\u5c0f\u00a0\u4ee3\u4ef7\u3002\u5982\u679c\u8def\u5f84\u4e0d\u5b58\u5728\uff0c\u8fd4\u56de\u00a0-1\u00a0\u3002\u4e00\u6761\u8def\u5f84\u7684\u4ee3\u4ef7\u662f\u8def\u5f84\u4e2d\u6240\u6709\u8fb9\u4ee3\u4ef7\u4e4b\u548c\u3002\n\n\u00a0\n\n\u793a\u4f8b 1\uff1a\n\n```\n\u8f93\u5165\uff1a\n[\"Graph\", \"shortestPath\", \"shortestPath\", \"addEdge\", \"shortestPath\"]\n[[4, [[0, 2, 5], [0, 1, 2], [1, 2, 1], [3, 0, 3]]], [3, 2], [0, 3], [[1, 3, 4]], [0, 3]]\n\u8f93\u51fa\uff1a\n[null, 6, -1, null, 6]\n\n\u89e3\u91ca\uff1a\nGraph g = new Graph(4, [[0, 2, 5], [0, 1, 2], [1, 2, 1], [3, 0, 3]]);\ng.shortestPath(3, 2); // \u8fd4\u56de 6 \u3002\u4ece 3 \u5230 2 \u7684\u6700\u77ed\u8def\u5f84\u5982\u7b2c\u4e00\u5e45\u56fe\u6240\u793a\uff1a3 -> 0 -> 1 -> 2 \uff0c\u603b\u4ee3\u4ef7\u4e3a 3 + 2 + 1 = 6 \u3002\ng.shortestPath(0, 3); // \u8fd4\u56de -1 \u3002\u6ca1\u6709\u4ece 0 \u5230 3 \u7684\u8def\u5f84\u3002\ng.addEdge([1, 3, 4]); // \u6dfb\u52a0\u4e00\u6761\u8282\u70b9 1 \u5230\u8282\u70b9 3 \u7684\u8fb9\uff0c\u5f97\u5230\u7b2c\u4e8c\u5e45\u56fe\u3002\ng.shortestPath(0, 3); // \u8fd4\u56de 6 \u3002\u4ece 0 \u5230 3 \u7684\u6700\u77ed\u8def\u5f84\u4e3a 0 -> 1 -> 3 \uff0c\u603b\u4ee3\u4ef7\u4e3a 2 + 4 = 6 \u3002\n```\n\n\u00a0\n\n\u63d0\u793a\uff1a\n\n\t1 <= n <= 100\n\n\t0 <= edges.length <= n * (n - 1)\n\n\tedges[i].length == edge.length == 3\n\n\t0 <= fromi, toi, from, to, node1, node2 <= n - 1\n\n\t1 <= edgeCosti, edgeCost <= 106\n\n\t\u56fe\u4e2d\u4efb\u4f55\u65f6\u5019\u90fd\u4e0d\u4f1a\u6709\u91cd\u8fb9\u548c\u81ea\u73af\u3002\n\n\t\u8c03\u7528 addEdge\u00a0\u81f3\u591a\u00a0100\u00a0\u6b21\u3002\n\n\t\u8c03\u7528 shortestPath\u00a0\u81f3\u591a\u00a0100\u00a0\u6b21\u3002",
    "\u6bcf\u884c\u4e00\u4e2a\u53c2\u6570\uff08JSON \u683c\u5f0f\uff09\uff0c\u4f9d\u6b21\u4e3a\uff1a\u3002",
    "\u8f93\u51fa boolean \u7c7b\u578b\u7ed3\u679c\uff08JSON \u5e8f\u5217\u5316\uff09\u3002",
    "",
    "import sys, json\nimport itertools, functools, collections, math, bisect, string, heapq, random, operator\nfrom typing import *\nfrom collections import *\nfrom itertools import *\nfrom bisect import *\nfrom functools import *\nfrom math import *\nfrom string import *\nfrom operator import *\nclass Graph:\n    def __init__(self, n: int, edges: List[List[int]]):\n        self.graph = [[] for _ in range(n)]\n        for x, y, cost in edges:\n            self.graph[x].append((y, cost))\n\n    def addEdge(self, edge: List[int]) -> None:\n        x, y, cost = edge[0], edge[1], edge[2]\n        self.graph[x].append((y, cost))  \n\n    def shortestPath(self, node1: int, node2: int) -> int: \n        dist = [inf] * len(self.graph)\n        dist[node1] = 0\n        q = [(0, node1)]\n        while q:\n            cost, x = heapq.heappop(q)\n            if x == node2:\n                return cost\n            for y, ncost in self.graph[x]:\n                if dist[y] > cost + ncost:\n                    dist[y] = cost + ncost\n                    heapq.heappush(q, [cost + ncost, y])\n        return -1\n\ndef main():\n    _lines = [x for x in sys.stdin.read().split('\\n') if x.strip() != '']\n    _ops = json.loads(_lines[0])\n    _args = json.loads(_lines[1]) if len(_lines) > 1 else []\n    _obj = None\n    _out = []\n    for _i, _op in enumerate(_ops):\n        _a = _args[_i] if _i < len(_args) else []\n        if _i == 0:\n            _obj = Graph(*_a)\n            _out.append(None)\n        else:\n            _out.append(getattr(_obj, _op)(*_a))\n    print(json.dumps(_out, separators=(',', ':')))\n\nmain()\n",
