    "\u8f93\u51fa integer \u7c7b\u578b\u7ed3\u679c\uff08JSON \u5e8f\u5217\u5316\uff09\u3002",
    "",
    "import sys, json\nimport itertools, functools, collections, math, bisect, string, heapq, random, operator\nfrom typing import *\nfrom collections import *\nfrom itertools import *\nfrom bisect import *\nfrom functools import *\nfrom math import *\nfrom string import *\nfrom operator import *\n\nclass Solution:\n    def evenSumSubgraphs(self, nums: list[int], edges: list[list[int]]) -> int:\n        n = len(nums)\n        tgt = 1 << n\n        dp = [False] * tgt        \n        road = defaultdict(list)\n        for x,y in edges:  \n            road[x].append(y)       \n            road[y].append(x)\n        # \u5355\u70b9\u5f53\u7136\u8fde\u901a\n        for i in range(n):\n            dp[1 << i] = True\n        \n        for s in range(tgt):\n            # \u975e\u8fde\u901a\n            if not dp[s]:\n                continue\n            \n            for i in range(n):\n                # \u4e0d\u5728s\u4e2d\n                if not (1 << i)&s:\n                    continue\n                # \u8fb9\n                for j in road[i]:\n                    dp[s|(1<<j)] = True\n        \n        res = 0         \n        for s in range(tgt):\n            if not dp[s]:\n                continue\n            t = 0\n            for i in range(n):\n                if (1<<i)&s:\n                    t += nums[i]\n            if not t&1:\n                res += 1\n        return res\n\ndef main():\n    _dec = json.JSONDecoder()\n    _text = sys.stdin.read()\n    _idx = 0\n    _args = []\n    while _idx < len(_text):\n        while _idx < len(_text) and _text[_idx] in ' \\t\\r\\n':\n            _idx += 1\n        if _idx >= len(_text):\n            break\n        try:\n            _obj, _end = _dec.raw_decode(_text, _idx)\n            _args.append(_obj)\n            _idx = _end\n        except Exception:\n            _nl = _text.find('\\n', _idx)\n            if _nl == -1:\n                _idx = len(_text)\n            else:\n                _idx = _nl + 1\n    _sol = Solution()\n\n    _ret = _sol.evenSumSubgraphs(_args[0], _args[1])\n    if _ret is None:\n        _out = ''\n    elif isinstance(_ret, (list, dict)):\n        _out = json.dumps(_ret, separators=(',', ':'))\n    elif isinstance(_ret, bool):\n        _out = 'true' if _ret else 'false'\n    elif isinstance(_ret, float):\n        _out = repr(_ret)\n    else:\n        _out = str(_ret)\n    sys.stdout.write(_out)\n\nmain()\n",
