    "",
    "import sys, json\nimport itertools, functools, collections, math, bisect, string, heapq, random, operator\nfrom typing import *\nfrom collections import *\nfrom itertools import *\nfrom bisect import *\nfrom functools import *\nfrom math import *\nfrom string import *\nfrom operator import *\n\nclass Solution:\n    def distanceLimitedPathsExist(self, n: int, edgeList: List[List[int]], queries: List[List[int]]) -> List[bool]:\n        edgeList.sort(key=lambda e: e[2])\n\n        # \u5e76\u67e5\u96c6\u6a21\u677f\n        fa = list(range(n))\n        def find(x: int) -> int:\n            if fa[x] != x:\n                fa[x] = find(fa[x])\n            return fa[x]\n        def merge(from_: int, to: int) -> None:\n            fa[find(from_)] = find(to)\n\n        ans, k = [False] * len(queries), 0\n        # \u67e5\u8be2\u7684\u4e0b\u6807\u6309\u7167 limit \u4ece\u5c0f\u5230\u5927\u6392\u5e8f\uff0c\u65b9\u4fbf\u79bb\u7ebf\n        for i, (p, q, limit) in sorted(enumerate(queries), key=lambda p: p[1][2]):\n            while k < len(edgeList) and edgeList[k][2] < limit:\n                merge(edgeList[k][0], edgeList[k][1])\n                k += 1\n            ans[i] = find(p) == find(q)\n        return ans\n\ndef main():\n    _dec = json.JSONDecoder()\n    _text = sys.stdin.read()\n    _idx = 0\n    _args = []\n    while _idx < len(_text):\n        while _idx < len(_text) and _text[_idx] in ' \\t\\r\\n':\n            _idx += 1\n        if _idx >= len(_text):\n            break\n        try:\n            _obj, _end = _dec.raw_decode(_text, _idx)\n            _args.append(_obj)\n            _idx = _end\n        except Exception:\n            _nl = _text.find('\\n', _idx)\n            if _nl == -1:\n                _idx = len(_text)\n            else:\n                _idx = _nl + 1\n    _sol = Solution()\n\n    _ret = _sol.distanceLimitedPathsExist(_args[0], _args[1], _args[2])\n    if _ret is None:\n        _out = ''\n    elif isinstance(_ret, (list, dict)):\n        _out = json.dumps(_ret, separators=(',', ':'))\n    elif isinstance(_ret, bool):\n        _out = 'true' if _ret else 'false'\n    elif isinstance(_ret, float):\n        _out = repr(_ret)\n    else:\n        _out = str(_ret)\n    sys.stdout.write(_out)\n\nmain()\n",
